package com.mall.service.impl;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.mall.entity.StockSubscription; import com.mall.mapper.StockSubscriptionMapper; import com.mall.service.NotificationService; import com.mall.service.StockSubscriptionService; import com.mall.vo.StockSubscriptionVO; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service public class StockSubscriptionServiceImpl implements StockSubscriptionService { private final StockSubscriptionMapper mapper; private final NotificationService notifications; public StockSubscriptionServiceImpl(StockSubscriptionMapper mapper,NotificationService notifications){this.mapper=mapper;this.notifications=notifications;} @Override @Transactional public void subscribe(Long userId,Long productId,Long skuId){var q=new LambdaQueryWrapper<StockSubscription>().eq(StockSubscription::getUserId,userId).eq(StockSubscription::getProductId,productId).eq(skuId!=null,StockSubscription::getSkuId,skuId).isNull(skuId==null,StockSubscription::getSkuId);var existing=mapper.selectOne(q);if(existing==null){var s=new StockSubscription();s.setUserId(userId);s.setProductId(productId);s.setSkuId(skuId);s.setStatus(0);s.setCreateTime(LocalDateTime.now());s.setUpdateTime(LocalDateTime.now());mapper.insert(s);}else if(existing.getStatus()!=0){existing.setStatus(0);existing.setNotifiedTime(null);existing.setUpdateTime(LocalDateTime.now());mapper.updateById(existing);}} @Override @Transactional public void unsubscribe(Long userId,Long productId,Long skuId){mapper.delete(new LambdaQueryWrapper<StockSubscription>().eq(StockSubscription::getUserId,userId).eq(StockSubscription::getProductId,productId).eq(skuId!=null,StockSubscription::getSkuId,skuId).isNull(skuId==null,StockSubscription::getSkuId));} @Override public java.util.List<StockSubscriptionVO> list(Long userId){return mapper.selectActiveSubscriptionsByUserId(userId);} @Override @Transactional public void notifyRestored(Long productId,Long skuId){var rows=mapper.selectList(new LambdaQueryWrapper<StockSubscription>().eq(StockSubscription::getProductId,productId).eq(StockSubscription::getStatus,0).and(q->q.eq(StockSubscription::getSkuId,skuId).or().isNull(StockSubscription::getSkuId)));for(var s:rows){notifications.notify(s.getUserId(),"STOCK","商品已补货","您订阅的商品库存已恢复，可前往商品详情页购买。","PRODUCT",productId);s.setStatus(1);s.setNotifiedTime(LocalDateTime.now());s.setUpdateTime(LocalDateTime.now());mapper.updateById(s);}} }
